<?php $isCycle=$tab==='cycles';$kind=$isCycle?'cycle':'module';$items=$isCycle?$cycles:$modules;$statuses=$isCycle?['planned'=>'Planned','active'=>'Active','completed'=>'Completed']:['planned'=>'Planned','in_progress'=>'In progress','paused'=>'Paused','completed'=>'Completed','cancelled'=>'Cancelled']; ?>
<div class="section-heading"><div><h2><?= $isCycle?'Cycles':'Modules' ?></h2><p class="muted"><?= $isCycle?'Time-box your work and track real completion.':'Break a larger project into manageable parts.' ?></p></div><a class="btn" href="#work-new-group">+ <?= ucfirst($kind) ?></a></div>
<?php if(!$items): ?><section class="card empty"><h3><?= $isCycle?'Find your next rhythm.':'Make a big project feel smaller.' ?></h3><p><?= $isCycle?'Create a cycle, then assign work items to it.':'Create a module, then group related work items together.' ?></p></section><?php else: ?><div class="website-grid"><?php foreach($items as $grouping):$percentage=$grouping['total']>0?$grouping['completed']/$grouping['total']*100:0; ?><article class="card work-group-card"><div class="section-heading"><h2><?= e($grouping['name']) ?></h2><span class="badge"><?= e($statuses[$grouping['status']]) ?></span></div><p class="muted"><?= e($grouping['description']) ?></p><?= progress_donut($percentage,'Work completed',$grouping['completed'].' of '.$grouping['total'].' work items',true,$isCycle?'blue':'violet') ?><p class="footnote"><?= $isCycle?e(($grouping['starts_on']??'Dates not set').($grouping['ends_on']?' → '.$grouping['ends_on']:'')):($grouping['target_date']?'Target '.e($grouping['target_date']):'No target date') ?></p><a href="<?= $workPath ?>?<?= e(http_build_query([$kind=>$grouping['id']])) ?>">View work items <?= icon('arrow-right') ?></a><details><summary>Edit <?= $kind ?></summary><?php $groupForm=$grouping;require __DIR__.'/group-form.php'; ?></details><?php if($isCycle&&$grouping['status']!=='completed'): ?><details><summary>Complete cycle</summary><form class="stack" method="post" action="<?= $workPath ?>/cycle/<?= e($grouping['id']) ?>/complete"><?= csrf_field() ?><label>Move unfinished work to<select name="move_to"><option value="">Keep it in this cycle</option><?php foreach($cycles as $target):if($target['id']===$grouping['id']||$target['status']==='completed')continue; ?><option value="<?= e($target['id']) ?>"><?= e($target['name']) ?></option><?php endforeach; ?></select></label><button class="secondary">Complete cycle</button></form></details><?php endif; ?><?php if($isCycle):$snapshots=Db::all('SELECT day,total,completed FROM work_snapshots WHERE project_id=? AND cycle_id=? ORDER BY day',[$project['id'],$grouping['id']]);if($snapshots): ?><details><summary>Completion history</summary><?= chart('line',array_column($snapshots,'day'),[['label'=>'Remaining work items','data'=>array_map(fn($row)=>(int)$row['total']-(int)$row['completed'],$snapshots),'borderColor'=>'#3688ff','tension'=>.25]],['scales'=>['y'=>['beginAtZero'=>true,'ticks'=>['precision'=>0]]]]) ?><p class="footnote">Snapshots come from actual updates. Past dates are not estimated.</p></details><?php endif;endif; ?></article><?php endforeach; ?></div><?php endif; ?>
<section class="card" id="work-new-group"><h2>Create <?= $isCycle?'a cycle':'a module' ?></h2><?php $groupForm=null;require __DIR__.'/group-form.php'; ?></section>
